class KeyboardTests {
 static int checks;static void A(bool ok,string text){if(!ok)throw new Exception(text);checks++;Console.WriteLine("PASS "+text);}
 static AudioClip Clip(){return new AudioClip(new float[256],new float[256],120,1);}
 static Engine Fresh(){Engine e=new Engine();e.Config.Quantize=false;e.Config.Gate=0;for(int i=0;i<5;i++)e.Tracks[i].Config.LoopSync=false;return e;}
