 static object Field(object o,string name){return o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).GetValue(o);}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Directory.CreateDirectory("work/keyboard-tests");string settings=Path.Combine(Storage.DataDirectory,"settings.json");byte[] backup=File.Exists(settings)?File.ReadAllBytes(settings):null;try{
  Engine e=Fresh();e.System.KeyboardBindings=Bind("track.0.cycle",Keys.Q);KeyboardController router=new KeyboardController(e,delegate{});A(router.Down(Keys.Q)&&e.Tracks[0].State==PlayState.Recording,"custom Q controls track 1 circle");router.Down(Keys.Q);A(e.Tracks[0].State==PlayState.Recording,"held key never retriggers record on auto-repeat");router.Up(Keys.Q);A(!router.Down(Keys.D1),"replaced default key no longer triggers action");
