  e=Fresh();e.System.KeyboardBindings=Bind("fx.track.slot.0.hold",Keys.H);router=new KeyboardController(e,delegate{});router.Down(Keys.H);FxConfig first=e.Config.TrackFx.Slots[0];A(first.On,"hold FX turns on");e.Config.TrackFx.Bank=1;router.Up(Keys.H);A(!first.On&&!e.Config.TrackFx.Slots[4].On,"release affects original FX even after bank change");router.Down(Keys.H);router.ReleaseAll();A(!e.Config.TrackFx.Slots[4].On,"focus loss releases held FX");
  e.Config.TrackFx.Slots[4].On=true;router.Down(Keys.H);router.Up(Keys.H);A(e.Config.TrackFx.Slots[4].On,"hold restores previously active FX state");
  e.System.KeyboardBindings=Bind("fx.track.slot.1.toggle",Keys.F6);e.Config.TrackFx.Slots[5].Momentary=true;router.Down(Keys.F6);router.Up(Keys.F6);A(!e.Config.TrackFx.Slots[5].On,"normal toggle binding respects momentary slot configuration");
  e.System.KeyboardEnabled=false;A(!router.Down(Keys.F6),"keyboard can be disabled");e.System.KeyboardEnabled=true;
  e=Fresh();e.Config.SelectedTrack=3;router=new KeyboardController(e,delegate{});router.Execute("selected.levelup");A(Math.Abs(e.Tracks[3].Config.Level-.85f)<.0001,"selected track volume shortcut adjusts correct fader");e.Import(1,Clip());router.Execute("track.1.play");A(e.Tracks[1].Playing,"dedicated PLAY command");router.Execute("track.1.dub");A(e.Tracks[1].State==PlayState.Overdubbing,"dedicated OVERDUB command");router.Execute("track.1.stop");A(!e.Tracks[1].Playing,"dedicated STOP command");
  e=Fresh();HashSet<string> identifiers=new HashSet<string>();foreach(KeyboardCommand command in KeyboardCatalog.Commands){AUnique(identifiers.Add(command.Id),command.Id);router=new KeyboardController(e,delegate{});Action up=router.Execute(command.Id);if(up!=null)up();}A(identifiers.Count==KeyboardCatalog.Commands.Count,"every catalog action has an executable handler ("+identifiers.Count+" actions)");
  A(KeyboardCatalog.InvalidKey(Keys.Control|Keys.Alt|Keys.Delete)!=null&&KeyboardCatalog.InvalidKey(Keys.Alt|Keys.F4)!=null,"Windows reserved shortcuts are rejected");A(KeyboardCatalog.InvalidKey(Keys.Space)==null&&KeyboardCatalog.InvalidKey(Keys.Escape)==null,"Space and Esc can be assigned");A(KeyboardCatalog.InvalidKey((Keys)(0x100000|65))!=null,"invalid modifier bits rejected");bool invalid=false;try{KeyboardCatalog.Validate(new List<KeyBinding>{new KeyBinding{Action="track.0.cycle",Key=81},new KeyBinding{Action="track.1.cycle",Key=81}});}catch{invalid=true;}A(invalid,"duplicate-key profiles rejected");
  SystemConfig legacy=Storage.FromJson<SystemConfig>(System.Text.Encoding.UTF8.GetBytes("{\"InputDevice\":-1}"));KeyDefaults.Ensure(legacy);A(legacy.KeyboardEnabled&&legacy.KeyboardBindings.Count>0,"old settings migrate with default keyboard enabled");SystemConfig disabled=Storage.Clone(new SystemConfig{KeyboardEnabled=false});A(!disabled.KeyboardEnabled,"disabled keyboard survives settings serialization");
  // Regression: no sample from before the visible recording cue enters the take.
