  e=Fresh();e.RequireRecordAcknowledgement=true;using(NativeAudio live=new NativeAudio(e)){e.FreshInputBoundary=live.FreshCaptureBoundary;live.Start();System.Threading.Thread.Sleep(80);long boundary=live.FreshCaptureBoundary();A(boundary>=0&&boundary<441000,"native capture position provides a valid recording boundary");e.Action(0);for(int wait=0;wait<50&&e.Tracks[0].FreshRecordedFrames==0;wait++)System.Threading.Thread.Sleep(10);A(e.Tracks[0].FreshRecordedFrames>0,"native input is captured even before GUI repaint");e.AcknowledgeRecordingVisible(0);System.Threading.Thread.Sleep(100);A(e.Tracks[0].FreshRecordedFrames>0,"native fresh audio flows after visible cue boundary");live.Stop();}
  using(MainForm f=new MainForm()){f.Opacity=0;f.Show();Application.DoEvents();((System.Windows.Forms.Timer)Field(f,"timer")).Stop();f.Audio.Stop();SettingsPage options=(SettingsPage)Field(f,"settingsPage");KeyboardPage page=options.KeyboardOptions;SystemConfig original=Storage.Clone(f.Engine.System);try{
   f.Engine.System.KeyboardEnabled=true;page.Assign("track.0.cycle",Keys.Q,true);A(Storage.LoadSystem().KeyboardBindings.Exists(delegate(KeyBinding b){return b.Action=="track.0.cycle"&&b.Key==(int)Keys.Q;}),"UI assignments persist to settings file");invalid=false;try{page.Assign("track.1.cycle",Keys.Q,false);}catch{invalid=true;}A(invalid,"UI prevents conflict without replacement decision");page.Assign("track.1.cycle",Keys.Q,true);A(page.Conflict("track.1.cycle",Keys.Q)==null&&!f.Engine.System.KeyboardBindings.Exists(delegate(KeyBinding b){return b.Action=="track.0.cycle";}),"conflict replacement moves key without duplicate mappings");
   string path="work/keyboard-tests/profile.loopkeys";page.WriteProfile(path);page.Assign("track.1.cycle",Keys.W,true);page.ReadProfile(path);A(f.Engine.System.KeyboardBindings.Exists(delegate(KeyBinding b){return b.Action=="track.1.cycle"&&b.Key==(int)Keys.Q;}),"keyboard profile export/import roundtrip");
   TabControl tabs=(TabControl)Field(f,"tabs");f.ShowOptions();options.ShowKeyboard();Application.DoEvents();A(!tabs.Visible&&page.Visible,"Options Keyboard page reachable");using(Bitmap b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(0,0,b.Width,b.Height));b.Save("work/keyboard-tests/Opciones-Teclado.png");}
   f.ShowMainPage(0);f.ActiveControl=null;for(int attempt=0;attempt<20;attempt++){f.Activate();Application.DoEvents();if(Form.ActiveForm==f)break;System.Threading.Thread.Sleep(10);}KeyboardMessageFilter filter=new KeyboardMessageFilter(f,delegate{return true;},delegate{return Keys.None;});Message key=Message.Create(f.Handle,0x100,(IntPtr)(int)Keys.Q,IntPtr.Zero);bool handled=filter.PreFilterMessage(ref key);A(handled&&f.Engine.Tracks[1].State==PlayState.Recording,"window message filter routes custom key to track 2");A(!f.Engine.Tracks[1].AwaitingRecordVisible,"recording cue is painted and acknowledged immediately on key press");Message up=Message.Create(f.Handle,0x101,(IntPtr)(int)Keys.Q,IntPtr.Zero);filter.PreFilterMessage(ref up);TextBox name=(TextBox)Field(f,"sessionName");name.Focus();Application.DoEvents();key=Message.Create(name.Handle,0x100,(IntPtr)(int)Keys.Q,IntPtr.Zero);A(!filter.PreFilterMessage(ref key),"typing in text fields never triggers performance shortcuts");
   using(KeyCaptureDialog capture=new KeyCaptureDialog("Pista 1")){Message msg=Message.Create(IntPtr.Zero,0x100,(IntPtr)(int)Keys.J,IntPtr.Zero);typeof(KeyCaptureDialog).GetMethod("ProcessCmdKey",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(capture,new object[]{msg,Keys.Control|Keys.J});A(capture.Captured==(Keys.Control|Keys.J)&&capture.DialogResult==DialogResult.OK,"key capture dialog recognizes modifier chord");}
  }finally{f.Keyboard.ReleaseAll();f.Engine.System=original;f.Engine.Dirty=false;f.Close();}}
  Console.WriteLine("TOTAL "+checks+" keyboard and recording regression checks passed");
 }catch(Exception ex){Console.WriteLine("FAIL "+ex);Environment.ExitCode=1;}finally{if(backup!=null){Directory.CreateDirectory(Storage.DataDirectory);File.WriteAllBytes(settings,backup);}else if(File.Exists(settings))File.Delete(settings);}}
 static void AUnique(bool ok,string id){if(!ok)throw new Exception("Duplicate action: "+id);}
}
